tionStatus // ACTIVE | COMPLETED | STOPPED | ON_HOLD\n  stopReason   String?\n  isChronicMed Boolean          @default(false)\n\n  // interactions (flagged by system)\n  hasInteractionFlag Boolean @default(false)\n  interactionNote    String?\n\n  // source\n  facilityId       String?\n  prescribedBy     String?\n  dispensedBy      String?\n  fhirResourceJson Json?\n\n  createdAt DateTime @default(now())\n\n  @@map(\"medications\")\n}\n\n// ─────────────────────────────────────────────\n// IDENTITY MATCH LOG\n// Every matching decision — automated or manual\n// Full audit trail of how records got linked\n// ─────────────────────────────────────────────\n\nmodel MatchLog {\n  id String @id @default(cuid())\n\n  // what was being matched\n  sourceRecordId    String\n  sourceRecord      SourcePatientRecord @relation(fields: [sourceRecordId], references: [id])\n  candidateMasterId String?\n  masterPatient     MasterPatient?      @relation(fields: [candidateMasterId], references: [id])\n\n  // match result\n  matchStatus     MatchStatus // AUTO_MATCHED | MANUAL_MATCHED | NO_MATCH | REVIEW\n  confidenceScore Float // 0.0 - 1.0\n  matchMethod     MatchMethod // NATIONAL_ID | PROBABILISTIC | IPRS | MANUAL\n\n  // score breakdown (how confidence was calculated)\n  nationalIdScore Float? // 1.0 if exact match, 0 if missing\n  nameScore       Float? // Jaro-Winkler similarity\n  dobScore        Float? // 1.0 exact, 0.5 year only, 0 mismatch\n  phoneScore      Float?\n  genderScore     Float?\n  iprsScore       Float?\n\n  // decision\n  decidedBy   String? // \"SYSTEM_AUTO\" or userId\n  decidedAt   DateTime @default(now())\n  reviewNotes String? // if human reviewed\n\n  // what triggered this match attempt\n  triggerEvent String? // \"SYNC_KNH\" | \"MANUAL_REVIEW\" | \"API_INGEST\"\n\n  createdAt DateTime @default(now())\n\n  @@map(\"match_logs\")\n}\n\n// ─────────────────────────────────────────────\n// MERGE LOG\n// When two master records are merged into one\n// ─────────────────────────────────────────────\n\nmodel MergeLog {\n  id String @id @default(cuid())\n\n  // which records were merged\n  sourcePatientId String // the record that got merged away\n  targetPatientId String // the surviving master record\n\n  // relations (owns the FKs)\n  mergedFrom MasterPatient @relation(\"MergedFrom\", fields: [sourcePatientId], references: [id])\n  mergedInto MasterPatient @relation(\"MergedInto\", fields: [targetPatientId], references: [id])\n\n  // decision\n  mergedBy        String // userId or \"SYSTEM_AUTO\"\n  mergedAt        DateTime @default(now())\n  mergeReason     String?\n  confidenceScore Float?\n\n  // snapshot of source record before merge (for recovery)\n  sourceSnapshot Json\n\n  createdAt DateTime @default(now())\n\n  @@map(\"merge_logs\")\n}\n\n// ─────────────────────────────────────────────\n// RISK SCORES\n// ML-generated patient risk assessments\n// Stored separately so they can be updated\n// without touching the immutable health records\n// ─────────────────────────────────────────────\n\nmodel RiskScore {\n  id String @id @default(cuid())\n\n  masterPatientId String\n  masterPatient   MasterPatient @relation(fields: [masterPatientId], references: [id])\n\n  scoreType    String // \"CHRONIC_DISEASE\" | \"READMISSION\" | \"MEDICATION_ADHERENCE\"\n  scoreValue   Float // 0.0 - 1.0\n  scoreLabel   String // \"Low\" | \"Medium\" | \"High\" | \"Critical\"\n  modelVersion String // which ML model version generated this\n  factors      Json // contributing factors as JSON array\n  validUntil   DateTime // scores expire and get recalculated\n\n  calculatedAt DateTime @default(now())\n\n  @@map(\"risk_scores\")\n}\n\n// ─────────────────────────────────────────────\n// SYNC LOGS\n// Track every data pull from each facility\n// ─────────────────────────────────────────────\n\nmodel SyncLog {\n  id String @id @default(cuid())\n\n  facilityId String\n  facility   Facility @relation(fields: [facilityId], references: [id])\n\n  syncType         String // \"FULL\" | \"INCREMENTAL\" | \"PATIENT\" | \"ENCOUNTER\"\n  status           SyncStatus // STARTED | COMPLETED | FAILED | PARTIAL\n  recordsPulled    Int        @default(0)\n  recordsProcessed Int        @default(0)\n  recordsFailed    Int        @default(0)\n  newPatients      Int        @default(0)\n  matchedPatients  Int        @default(0)\n  reviewQueue      Int        @default(0) // flagged for human review\n\n  startedAt    DateTime  @default(now())\n  completedAt  DateTime?\n  errorMessage String?\n  syncMetadata Json? // additional context\n\n  @@map(\"sync_logs\")\n}\n",
